import express, { type NextFunction, type Request, type Response } from "express";
import type { OrderService } from "../application/order-service";
import { DomainError } from "../domain/errors";
import type { Order, OrderLine, OrderState } from "../domain/order";

const STATUS = {
  not_found: 404,
  invalid: 400,
  insufficient_stock: 409,
  invalid_transition: 409,
} as const;

const ACTIONS: ReadonlyArray<readonly [string, OrderState]> = [
  ["pay", "paid"],
  ["pack", "packed"],
  ["ship", "shipped"],
  ["deliver", "delivered"],
];

function view(o: Order) {
  return {
    id: o.id,
    customerId: o.customerId,
    state: o.state,
    items: o.lines,
    placedAt: o.placedAt.toISOString(),
  };
}

function param(req: Request, name: string): string {
  const v = req.params[name];
  return Array.isArray(v) ? v.join("/") : (v ?? "");
}

export function createApp(service: OrderService): express.Express {
  const app = express();
  app.use(express.json());

  app.get("/products", (_req, res) => {
    res.json(service.stockLevels());
  });
  app.post("/products", (req, res) => {
    const body = (req.body ?? {}) as { id?: string; name?: string; stock?: number };
    const p = service.addProduct(String(body.id ?? ""), String(body.name ?? ""), Number(body.stock));
    res.status(201).json(service.stockLevel(p.id));
  });
  app.get("/products/:id/stock", (req, res) => {
    res.json(service.stockLevel(param(req, "id")));
  });

  app.post("/orders", (req, res) => {
    const body = (req.body ?? {}) as { customerId?: string; items?: OrderLine[] };
    if (!Array.isArray(body.items)) throw new DomainError("invalid", "items must be an array");
    const order = service.placeOrder(String(body.customerId ?? ""), body.items);
    res.status(201).json(view(order));
  });
  app.get("/orders", (req, res) => {
    const state = typeof req.query.state === "string" ? req.query.state : undefined;
    res.json(service.listOrders(state).map(view));
  });
  app.get("/orders/:id", (req, res) => {
    res.json(view(service.getOrder(param(req, "id"))));
  });
  for (const [action, target] of ACTIONS) {
    app.post(`/orders/:id/${action}`, (req, res) => {
      res.json(view(service.advance(param(req, "id"), target)));
    });
  }
  app.post("/orders/:id/cancel", (req, res) => {
    res.json(view(service.cancel(param(req, "id"))));
  });

  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (err instanceof DomainError) {
      res.status(STATUS[err.code]).json({ error: err.code, message: err.message });
    } else if (err instanceof SyntaxError) {
      res.status(400).json({ error: "invalid", message: "malformed JSON" });
    } else {
      res.status(500).json({ error: "internal", message: "internal error" });
    }
  });
  return app;
}

